INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(501, 'Genesis 20:11', 'Genesis', 20, 11, '&nbsp;اِبراهيم جواب ورکړو، ”زما دا خيال وو چې دلته به داسې هيڅ څوک هم نۀ وى چې هغه د خُدائ پاک نه يريږى او دوئ به زما د ښځې په وجه ما ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(502, 'Genesis 20:12', 'Genesis', 20, 12, '&nbsp;هغه په رښتيا زما خور ده. هغه زما د پلار لور ده، خو زما د خپلې مور لور نۀ ده او ما هغه وادۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(503, 'Genesis 20:13', 'Genesis', 20, 13, '&nbsp;چې کله خُدائ پاک زۀ د خپل پلار د کور نه مسافر کړم، نو ما هغې ته ووئيل، تۀ به زما سره هغه وخت خپل غېرت څرګند کړې چې هر چا ته وائې چې زۀ ستا ورور يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(504, 'Genesis 20:14', 'Genesis', 20, 14, '&nbsp;بيا ابى‌مَلِک ساره واپس اِبراهيم ته ورکړه، هم هغه وخت يې هغۀ ته ګډې، څاروى او نوکران هم ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(505, 'Genesis 20:15', 'Genesis', 20, 15, '&nbsp;هغۀ اِبراهيم ته ووئيل، ”ګوره، دا ټوله زما زمکه ده، چې چرته دې خوښه وى هلته اوسېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(506, 'Genesis 20:16', 'Genesis', 20, 16, '&nbsp;هغۀ ساره ته ووئيل، ”زۀ ستا ورور له د سپينو زرو زر سيکې ورکوم، دا د دې دپاره چې تا سره څومره خلق دى چې ټولو ته ثابِته شى چې تۀ بې‌ګناه يې، هر چا ته به معلومه شى چې ستا لمن پاکه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(507, 'Genesis 21:1', 'Genesis', 21, 1, '&nbsp;مالِک خُدائ ساره له برکت ورکړو او خپله وعده يې ورسره پوره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(508, 'Genesis 21:2', 'Genesis', 21, 2, '&nbsp;اګر چې اِبراهيم په خپله ډېر بوډا وو، خو لکه څنګه چې خُدائ پاک ورته فرمائيلى وُو ساره اُميدواره شوه او هم په هغه صحيح وخت د هغې زوئ وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(509, 'Genesis 21:3', 'Genesis', 21, 3, '&nbsp;اِبراهيم په خپل زوئ اِسحاق نوم کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(510, 'Genesis 21:4', 'Genesis', 21, 4, '&nbsp;او چې اِسحاق د اتو ورځو شو، نو اِبراهيم هغه سنت کړو، هم هغه شان چې څنګه خُدائ پاک ورته حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(511, 'Genesis 21:5', 'Genesis', 21, 5, '&nbsp;اِبراهيم د سلو کالو وو چې اِسحاق پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(512, 'Genesis 21:6', 'Genesis', 21, 6, '&nbsp;نو ساره وفرمائيل، ”خُدائ پاک زۀ خندولې يم. اوس چې هر څوک د دې نه خبر شى نو زما سره به خاندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(513, 'Genesis 21:7', 'Genesis', 21, 7, '&nbsp;د دې نه مخکښې چا د دې وئيلو جرأت کولے شو چې يوه ورځ به زۀ خپل ماشوم له سينه ورکوم؟ خو ګورئ، په زوړ عُمر کښې د اِبراهيم زما نه زوئ پېدا شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(514, 'Genesis 21:8', 'Genesis', 21, 8, '&nbsp;چې ماشوم غټېدو او په خپله د روټۍ د خوړلو شو، نو په هغه ورځ اِبراهيم يو لوئ خېرات وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(515, 'Genesis 21:11', 'Genesis', 21, 11, '&nbsp;دې مسئلې اِبراهيم ډېر پرېشانه کړو، ځکه چې اِسمٰعيل خو هم د هغۀ زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(516, 'Genesis 21:12', 'Genesis', 21, 12, '&nbsp;خو خُدائ پاک وفرمائيل، ”اِبراهيمه، د خپلې وينځې او د هلک په حقله مۀ خفه کېږه. هم هغه شان وکړه چې څنګه درته ساره وائى ځکه چې هم د اِسحاق نه به ستا نسل قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(517, 'Genesis 21:13', 'Genesis', 21, 13, '&nbsp;خو د وينځې زوئ هم ستا زوئ دے او د هغۀ د اولاد نه به يو لوئ قوم جوړ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(518, 'Genesis 21:14', 'Genesis', 21, 14, '&nbsp;بل سحر وختى اِبراهيم پاڅېدو او هاجِرې له يې د اوبو ډک مشک او روټۍ ورکړه. او دا يې ورله په اوږو کېښودل او د زوئ سره يې رُخصت کړه. او هغه لاړه او بيرسبع ته نزدې په صحرا کښې سرګردانه ګرځېدله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(519, 'Genesis 21:15', 'Genesis', 21, 15, '&nbsp;او چې د هغوئ سره اوبۀ ختمې شوې، نو هاجِرې زوئ د يو بوټى لاندې کښېنولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(520, 'Genesis 21:16', 'Genesis', 21, 16, '&nbsp;او لږه لرې ترې کښېناسته، هغې د ځان سره ووئيل چې، ”زۀ دا نۀ شم زغملے چې د خپل زوئ مرګ ووينم.“ او هغه هلته ناسته وه سلګۍ يې وهلې او ژړل يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(521, 'Genesis 21:17', 'Genesis', 21, 17, '&nbsp;چې کله خُدائ پاک د هلک ژړا واورېده، نو د خُدائ پاک فرښتې د آسمان نه هاجِرې ته آواز وکړو او ورته يې وفرمائيل، ”هاجِرې، تۀ ولې پرېشانه يې؟ يرېږه مه. خُدائ پاک ستا د زوئ ژړا اورېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(522, 'Genesis 21:18', 'Genesis', 21, 18, '&nbsp;اوچت يې کړه او په غېږ کښې يې کښېنوه، ځکه چې زۀ به هغه د يو لوئ قوم پلار کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(523, 'Genesis 21:19', 'Genesis', 21, 19, '&nbsp;بيا خُدائ پاک د هغې سترګې کولاو کړې او د هغې نظر په چينې يو کوهى پرېوتو. نو هغه چينې له لاړه او مشک يې د اوبو نه ډک کړو او هلک له يې اوبۀ ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(524, 'Genesis 21:20', 'Genesis', 21, 20, '&nbsp;خُدائ پاک اِسمٰعيل له برکت ورکړو او چې هلک څنګه لوئ شو، نو د هغۀ نه يو تکړه تير انداز جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(525, 'Genesis 21:21', 'Genesis', 21, 21, '&nbsp;هغه د فاران په صحرا کښې اوسېدو، مور ورله يوه مِصرۍ جينۍ خوښه کړه او ورته يې وادۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(526, 'Genesis 21:22', 'Genesis', 21, 22, '&nbsp;تقريباً هم په هغه وخت ابى‌مَلِک او د هغۀ د لښکر مشر فيکُل اِبراهيم ته ووئيل، ”خُدائ پاک تا له په هر کار کښې برکت درکوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(527, 'Genesis 21:23', 'Genesis', 21, 23, '&nbsp;اوس زۀ غواړم چې تۀ د خُدائ پاک په نوم دا قَسم وکړې چې تۀ به زما سره دوکه نۀ کوې او همېشه به زما او زما د اولاد وفادار يې، لکه څنګه چې زۀ همېشه تا سره په دې مُلک کښې وفادار وم چې تۀ دلته مسافر وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(528, 'Genesis 21:24', 'Genesis', 21, 24, '&nbsp;نو اِبراهيم ورسره قَسم وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(529, 'Genesis 21:25', 'Genesis', 21, 25, '&nbsp;يوه ورځ، اِبراهيم ابى‌مَلِک ته شکايت وکړو چې، ”ستا يو څو نوکرانو زما په يو کوهى قبضه کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(530, 'Genesis 21:26', 'Genesis', 21, 26, '&nbsp;ابى‌مَلِک ورته ووئيل، ”دا خو ما ستا نه په وړومبى ځل واورېدل. تا ما ته مخکښې ولې ونۀ وئيل؟ ما ته پته نشته چې دا چا کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(531, 'Genesis 21:27', 'Genesis', 21, 27, '&nbsp;اِبراهيم ابى‌مَلِک ته ګډې او څۀ غواګانې ورکړې، نو د دوئ په مينځ کښې د امن معاهده وشوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(532, 'Genesis 21:28', 'Genesis', 21, 28, '&nbsp;اِبراهيم د خپلې رَمې نه اووۀ ګډې جدا کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(533, 'Genesis 21:29', 'Genesis', 21, 29, '&nbsp;او ابى‌مَلِک ترې تپوس وکړو، ”تا دا اووۀ ګډې ولې جدا کړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(534, 'Genesis 21:30', 'Genesis', 21, 30, '&nbsp;اِبراهيم جواب ورکړو، ”زۀ غواړم چې دا اووۀ ګډې زما نه قبولې کړې نو تۀ به ګواه يې چې ما دا کوهے کنستلے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(535, 'Genesis 21:31', 'Genesis', 21, 31, '&nbsp;نو په هغه ځائ يې بيرسبع نوم کېښودو، ځکه چې دوئ دواړو دلته معاهده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(536, 'Genesis 21:32', 'Genesis', 21, 32, '&nbsp;چې کله په بيرسبع کښې معاهده وشوه، نو ابى‌مَلِک او د هغۀ د لښکر مشر فيکُل واپس د فلستيانو مُلک ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(537, 'Genesis 21:33', 'Genesis', 21, 33, '&nbsp;اِبراهيم په بيرسبع کښې د غز ونه وکَرله او د مالِک خُدائ د ابدى خُدائ عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(538, 'Genesis 21:34', 'Genesis', 21, 34, '&nbsp;او اِبراهيم ډېر وخت مسافر وو او د فلستيانو په مُلک کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(539, 'Genesis 22:1', 'Genesis', 22, 1, '&nbsp;څۀ موده وروستو خُدائ پاک د اِبراهيم امتحان واخستو، هغۀ ته يې وفرمائيل، ”اِبراهيمه.“ نو اِبراهيم جواب ورکړو، ”زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(540, 'Genesis 22:2', 'Genesis', 22, 2, '&nbsp;خُدائ پاک ورته وفرمائيل، ”خپل زوئ روان کړه، خپل اېک يو زوئ اِسحاق، د کوم سره چې تۀ ډېره مينه کوې او د مورياه مُلک ته لاړ شه. هلته په يو غر باندې چې زۀ به يې درته ښايم، هغه ما ته د قربانۍ په توګه پېش کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(541, 'Genesis 22:3', 'Genesis', 22, 3, '&nbsp;نو اِبراهيم سحر وختى پاڅېدو، خپل خر يې کته کړو او خپل دوه ځوانان سړى او اِسحاق يې ځان سره روان کړل، هغۀ د سوزېدونکې قربانۍ دپاره لرګى پرې کړل او روان شو او هغه ځائ ته لاړو کوم چې خُدائ پاک ورته ښودلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(542, 'Genesis 22:4', 'Genesis', 22, 4, '&nbsp;په درېمه ورځ چې اِبراهيم وکتل نو د لرې نه يې هغه ځائ وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(543, 'Genesis 22:5', 'Genesis', 22, 5, '&nbsp;نو هغۀ نوکرانو ته وفرمائيل، ”دلته د خرۀ سره ايسار شئ. دا هلک او زۀ به هلته لاړ شُو او مونږ به عبادت وکړُو او واپس به تاسو له راشُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(544, 'Genesis 22:6', 'Genesis', 22, 6, '&nbsp;اِبراهيم په اِسحاق د قربانۍ لرګى يوړل او په خپله يې يوه چاړۀ او بل سکارۀ د اور بلولو دپاره يوړل. چې کله دوئ مزل کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(545, 'Genesis 22:7', 'Genesis', 22, 7, '&nbsp;نو اِسحاق وفرمائيل، ”پلاره.“ هغۀ جواب ورکړو، ”آو، زما زويه؟“ اِسحاق ترې تپوس وکړو، ”ما ته پته ده چې تا سره سکارۀ او لرګى شته، خو د قربانۍ دپاره ګډُورے چرته دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(546, 'Genesis 22:8', 'Genesis', 22, 8, '&nbsp;اِبراهيم جواب ورکړو، ”زما زويه، خُدائ پاک به په خپله د يو ګډ بندوبست وکړى.“ او دوئ دواړه روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(547, 'Genesis 22:9', 'Genesis', 22, 9, '&nbsp;کله چې هغه ځائ ته ورسېدل کوم چې ورته خُدائ پاک ښودلے وو، اِبراهيم يوه قربان‌ګاه جوړه کړه او لرګى يې پرې سم کېښودل. هغۀ خپل زوئ وتړلو او په قربان‌ګاه کښې يې د لرګو دپاسه کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(548, 'Genesis 22:10', 'Genesis', 22, 10, '&nbsp;بيا اِبراهيم د خپل زوئ حلالولو دپاره چاړۀ راواخستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(549, 'Genesis 22:11', 'Genesis', 22, 11, '&nbsp;خو ناڅاپه د مالِک خُدائ فرښتې د آسمان نه هغۀ ته وفرمائيل، ”اِبراهيمه، اِبراهيمه.“ هغۀ جواب ورکړو، ”زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(550, 'Genesis 22:12', 'Genesis', 22, 12, '&nbsp;فرښتې وفرمائيل، ”هلک له چې هيڅ تکليف ورنۀ کړې او نۀ ورته څۀ ووائې. ما ته پته ده چې تۀ د خُدائ پاک نه يرېږې، ځکه چې تا هغۀ ته خپل اېک يو زوئ هم پېش کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(551, 'Genesis 22:13', 'Genesis', 22, 13, '&nbsp;اِبراهيم څۀ ګورى چې يو ګډ د ښکرو نه په غنو کښې انښتے وو. هغه لاړو او راوې نيوو او د خپل زوئ په ځائ يې د سوزېدونکې قربانۍ په توګه پېش کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(552, 'Genesis 22:14', 'Genesis', 22, 14, '&nbsp;اِبراهيم په هغه ځائ ”مالِک خُدائ بندوبست کوى“ نوم کېښودو. او تر ننه پورې خلق وائى، ”د مالِک خُدائ په غر به بندوبست کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(553, 'Genesis 22:15', 'Genesis', 22, 15, '&nbsp;د مالِک خُدائ فرښتې په دوېم ځل د آسمان نه اِبراهيم ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(554, 'Genesis 22:16', 'Genesis', 22, 16, '&nbsp;”مالِک خُدائ فرمائى چې زۀ مالِک خُدائ په خپل نوم قسم کوم چې زۀ به تا له ډېر زيات برکت درکړم. ځکه چې تا دا وکړل او خپل اېک يو زوئ دې هم زما نه بچ ونۀ ساتلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(555, 'Genesis 22:17', 'Genesis', 22, 17, '&nbsp;زۀ دا وعده کوم چې زۀ به تا ته په رښتيا په برکتونو برکتونه درکوم او ستا اولاد به ډېر زياتوم لکه چې په آسمان کښې څومره ستورى دى او چې د سمندر په غاړه څومره شګې دى. ستا اولاد به خپلو دشمنانو له شکست ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(556, 'Genesis 22:18', 'Genesis', 22, 18, '&nbsp;ټول قومونه به ستا د اولاد په وسيله برکت ومومى. ځکه چې تا زما حُکم ومنلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
