(560, 'Genesis 22:24', 'Genesis', 22, 24, '&nbsp;د نحور د وينځې، رومه نه، طِبح، جاحم، تخص او معکه پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(561, 'Genesis 23:1', 'Genesis', 23, 1, '&nbsp;ساره يو سل اوويشت کاله ژوندۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(562, 'Genesis 23:2', 'Genesis', 23, 2, '&nbsp;هغه د کنعان په مُلک کښې په حبرون کښې په حق ورسېده، او اِبراهيم د ساره په غم غمژن شو او هغې پسې يې ژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
