(588, 'Genesis 24:10', 'Genesis', 24, 10, '&nbsp;د دې نه پس، هغه نوکر د اِبراهيم لس اوښان د ښو تُحفو سره بار کړل. بيا د شام شمال په طرف هغه ښار ته روان شو، چرته چې د اِبراهيم ورور نحور اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(589, 'Genesis 24:11', 'Genesis', 24, 11, '&nbsp;کله چې هغه هلته ورسېدو، هغۀ د ښار نه بهر د چينې سره نزدې اوښان کښېنول. دا د مازيګر وخت وو، چې کله ښځې اوبو وړلو له راووتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(590, 'Genesis 24:12', 'Genesis', 24, 12, '&nbsp;نوکر دُعا وکړه، ”تۀ مالِکه خُدايه پاکه، زما د نېک اِبراهيم خُدائ پاک يې، ما نن کامياب کړه او زما د نېک سره خپله وعده پوره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(591, 'Genesis 24:13', 'Genesis', 24, 13, '&nbsp;زۀ دلته د هغه چينې سره يم چې چرته به د ښار پېغلې اوبۀ وړلو له راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(592, 'Genesis 24:14', 'Genesis', 24, 14, '&nbsp;چې کومې جينۍ ته زۀ وايم چې لږ منګے راټيټ کړه، چې اوبۀ وڅښم، کۀ هغه ووائى چې وڅښه او زۀ به ستا اوښانو له هم اوبۀ راوړم، چې دا هم هغه وى چې تا خپل خِدمت کوونکى اِسحاق له خوښه کړې ده. کۀ داسې وشى، نو ما ته به پته ولګى چې تا زما د نېک سره خپله وعده پوره کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(593, 'Genesis 24:15', 'Genesis', 24, 15, '&nbsp;د دُعا ختمولو نه مخکښې، رِبقه چې د هغې په اوږو منګے وو راووتله. هغه د بتو‌اېل لور وه، چې هغه د اِبراهيم د ورور نحور او د هغۀ د ښځې مِلکاه زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(594, 'Genesis 24:16', 'Genesis', 24, 16, '&nbsp;هغه ډېره ښائسته جينۍ وه او لا وادۀ شوې نۀ وه. هغه لاندې چينې ته لاړه، منګے يې ډک کړو او راوختله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(595, 'Genesis 24:17', 'Genesis', 24, 17, '&nbsp;د اِبراهيم نوکر د مِلاوېدو دپاره هغې له ورمنډه کړل او ورته يې ووئيل، ”ستا د منګى نه ما له لږې اوبۀ راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(596, 'Genesis 24:18', 'Genesis', 24, 18, '&nbsp;هغې ووئيل، ”وڅښه، صاحِبه.“ او هغې زر د خپل ولى نه منګے راټيټ کړو او چې هغۀ اوبۀ څښلې نو منګے يې ورته نيولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(597, 'Genesis 24:19', 'Genesis', 24, 19, '&nbsp;چې کله هغې اوبۀ ورکړې، هغې ووئيل، ”زۀ به ستا اوښانو له هم اوبۀ راوړم تر هغه پورې چې تنده يې ماته شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(598, 'Genesis 24:20', 'Genesis', 24, 20, '&nbsp;هغې زر زر د څاروو د اوبو په سبيل کښې منګے تشولو او چينې ته به د نورو اوبو دپاره په منډه تله، تر دې پورې چې ټولو اوښانو ښۀ وڅښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(599, 'Genesis 24:21', 'Genesis', 24, 21, '&nbsp;د هغه سړى په هغې باندې نظر وو او غلے ولاړ وو، چې معلوم کړى چې مالِک خُدائ هغۀ له په سفر کښې کاميابى ورکړې ده کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(600, 'Genesis 24:22', 'Genesis', 24, 22, '&nbsp;چې کله اوښانو اوبۀ وڅښلې، هغه سړى د سرو زرو يوه قيمتى نتکۍ هغې ته ورپه پوزه کړه او دوه درنې د سرو زرو کَړى يې ورپه لاس کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');